BEGIN;
CREATE TABLE public.support_knowledge_articles (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  slug text NOT NULL UNIQUE,
  title text NOT NULL CHECK(length(btrim(title)) BETWEEN 1 AND 120),
  category text NOT NULL DEFAULT 'other' CHECK(category IN ('sales','billing','technical','other')),
  body text NOT NULL CHECK(length(btrim(body)) BETWEEN 1 AND 6000),
  is_active boolean NOT NULL DEFAULT true,
  created_at timestamptz NOT NULL DEFAULT now(),
  updated_at timestamptz NOT NULL DEFAULT now()
);
ALTER TABLE public.support_knowledge_articles ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON public.support_knowledge_articles FROM anon,authenticated;
GRANT SELECT,INSERT,UPDATE,DELETE ON public.support_knowledge_articles TO authenticated;
GRANT SELECT ON public.support_knowledge_articles TO service_role;
GRANT SELECT ON public.platform_addons TO service_role;
CREATE POLICY "Platform admins manage AI knowledge" ON public.support_knowledge_articles FOR ALL TO authenticated USING(public.is_platform_admin()) WITH CHECK(public.is_platform_admin());
CREATE TRIGGER update_support_knowledge_updated_at BEFORE UPDATE ON public.support_knowledge_articles FOR EACH ROW EXECUTE FUNCTION public.update_updated_at_column();
INSERT INTO public.support_knowledge_articles(slug,title,category,body) VALUES
('platform-overview','What ServeOS does','sales','ServeOS is a restaurant management platform. Each restaurant has its own website and menu, staff accounts, and subscription. Available modules include QR ordering, order management, POS, kitchen display, waiter service, tables, reservations, accounting, loyalty, promotions, themes, and domains. Features and limits depend on the current package and active add-ons. Use live package records to explain availability. Platform administrators manage the SaaS; restaurant owners manage their own restaurant.'),
('restaurant-signup-trial','Create a restaurant and start the seven-day trial','sales','Open /signup. Enter the restaurant name, an available public URL slug, owner email, and password. After creation, complete owner onboarding with restaurant details. New restaurants receive a seven-day free trial with no automatic charge. Existing restaurants do not receive a new trial simply by logging in again. When a trial expires, choose a paid package at /admin/subscription. Expired subscriptions restrict operations; the support team must review exceptional account or trial issues.'),
('restaurant-login','Restaurant owner, admin, and staff login','technical','Restaurant owners and staff use /staff-login or /r/{restaurant-slug}/admin-login. After login, an owner opens /owner, an admin or manager opens /admin, kitchen staff open /kitchen, and waiters open /waiter. The restaurant slug identifies its public URL. Staff must use the email and password created for their account. Customers use /r/{restaurant-slug}/login. Platform administrators use /platform/login. Never share demo or real credentials in a support answer.'),
('staff-accounts','Add kitchen staff and waiters','technical','Restaurant owners manage staff at /owner/staff. Restaurant admins manage staff at /admin/staff. Enter the staff email, password, and display name, choose Kitchen or Waiter, and create the account for that restaurant. Owners can also add managers. Staff sign in through /staff-login. Available staff slots depend on the package and staff-capacity add-ons. For a creation error, ask for the error text and restaurant slug, never the password. Permission or membership issues require human review.'),
('menu-management','Add menu categories, items, and images','technical','Restaurant menu management is at /admin/menu. Create or choose a category, then add an item with its name, description, price, availability, and image using the item editor. Review the correct restaurant and branch before saving. Guests browse /r/{restaurant-slug}/menu. Unavailable items are not listed as available for ordering. Prices display in the restaurant currency; platform package currency is separate. If an image is missing, check that the item has an image saved and its image URL loads.'),
('qr-tables','Table QR ordering and floor plans','technical','Manage restaurant tables at /admin/tables. Table QR links let guests open the restaurant menu and place orders for the table. Floor layouts are managed at /admin/floor-plans when enabled by the package or add-on. Test a QR link against the intended restaurant and table before displaying it. Do not invent a table number or QR URL; ask the restaurant to copy its generated link if needed.'),
('order-workflows','Orders, kitchen display, and waiter service','technical','Restaurant order management is at /admin/orders and POS at /admin/pos. Kitchen staff use /kitchen to work with kitchen tickets. Waiters use /waiter and can view service history at /waiter/history. Use role-specific accounts linked to the correct restaurant. If an order is missing, ask for its order reference, restaurant slug, and approximate time, then hand off for investigation. Never claim an order was changed or cancelled by the assistant.'),
('subscription-packages','Packages, prices, and renewals','billing','Restaurants choose paid packages at /admin/subscription. Use the supplied live package catalog for actual names, prices, features, and terms. Monthly, quarterly, biannual, and yearly terms cover one, three, six, and twelve months respectively. A price labelled price_monthly may be the total for the supplied multi-month term; do not divide or label every package monthly. Trial is seven days. Do not promise undocumented refunds, renewal discounts, or automatic payments.'),
('payment-review','Payment requests and approval','billing','Restaurant subscription checkout creates payment requests for the platform team to review. Payment methods and instructions come from the configured checkout options. Only platform administrators can approve or reject platform subscription payments at /platform/billing. Restaurant /admin/billing manages restaurant operations billing and is separate from SaaS subscription billing at /admin/subscription. For a pending payment, ask for the submitted payment reference and package, then request human review. Never ask for a payment PIN, password, or full card details.'),
('addon-marketplace','Optional add-ons and capacity packs','billing','Restaurant add-ons are available in the Add-ons section of /admin/subscription. /admin/addons redirects there. Use live add-on records for exact names, prices, monthly versus one-time billing, and capacity. A staff, menu, or branch pack adds the stated slots per purchased unit to a capped plan; it is unnecessary when that limit is already unlimited. Existing package features may already include an add-on capability. Demo-labelled products have sample prices. Requests are activated only after platform approval; the assistant cannot grant features.'),
('themes-branding','Restaurant website themes and branding','technical','Owners configure branding at /owner/branding and website appearance at /owner/theme. Platform administrators manage templates at /platform/themes and can assign a theme to a restaurant. Restaurant /admin/homepage and /admin/customizations manage available website content and customization options. Theme changes apply to the restaurant public website. Ask which restaurant and page are affected before investigating a display issue.'),
('custom-domain','Custom domains and public restaurant URLs','technical','Restaurant public pages use /r/{restaurant-slug}. Owners manage their custom domain at /owner/domain when custom-domain access is included. The domain setup page supplies DNS and verification instructions. Domain registration is separate from ServeOS access. DNS changes can require propagation before verification; do not guarantee a fixed completion time or invent DNS values. For verification problems, request the domain name and error message and hand off for investigation.'),
('business-tools','Accounting, loyalty, promotions, and reservations','technical','Restaurant accounting is at /admin/accounting, including sales, expenses, inventory, payroll, tax, and reports when enabled. Customer loyalty is at /admin/loyalty, promotions at /admin/promotions, and reservations at /admin/reservations. A missing or locked module may be due to the current subscription, role, or add-on access. Use supplied live entitlement details and avoid giving legal, tax, or financial advice.'),
('support-handoff','AI support, human support, and privacy','other','Restaurant support is at /admin/support. Website visitors can use the floating support chat button. The AI assistant answers platform usage questions from approved knowledge and current catalogs. A customer can ask for a human at any time. Account recovery, refunds, permissions, uncertain answers, attachments needing review, and provider failures are handed to the human inbox. Platform admins use /platform/support and Take over from AI. Never request passwords or API keys, disclose private team notes, or claim to access another restaurant data.'),
('troubleshooting','Troubleshoot loading and access problems','technical','For a slow or inaccessible page, ask for the page URL, what happens, browser, and exact error text. Suggest refreshing once and confirming the intended restaurant and account role. If the subscription has expired, open /admin/subscription to review an upgrade. Permission denied, Edge Function failures, persistent loading, or lost data require human investigation. Do not instruct users to reset or delete their database, disable security policies, or expose service keys.');
COMMIT;
